package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.OriginEnabledVO;

class OriginEnabledValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of origin enabled of observed source")
  void test_origin_enabled_value_holder_assign_plain_value() {
    Object holder = new Object();
    OriginEnabledValueHolder<Object> value = new OriginEnabledValueHolder<>(holder);
    Assertions.assertSame(holder, value.originEnabled(true), "Setters must return the holder");
    Assertions.assertTrue(value.getOriginEnabledValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getOriginEnabled().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of origin enabled of observed source")
  void test_origin_enabled_value_holder_assign_value_object() {
    Object holder = new Object();
    OriginEnabledValueHolder<Object> value = new OriginEnabledValueHolder<>(holder);
    OriginEnabledVO vo = OriginEnabledVO.from(true);
    Assertions.assertFalse(value.getOriginEnabledValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.originEnabled(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOriginEnabledValue().orElseThrow());
    Assertions.assertSame(holder, value.originEnabled(Optional.empty()));
    Assertions.assertFalse(value.getOriginEnabledValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.originEnabled(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOriginEnabledValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of origin enabled of observed source against the original")
  void test_origin_enabled_value_holder_read() {
    Object holder = new Object();
    OriginEnabledValueHolder<Object> value = new OriginEnabledValueHolder<>(holder);
    OriginEnabledVO vo = OriginEnabledVO.from(true);
    OriginEnabledVO other = OriginEnabledVO.from(true);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getOriginEnabledValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOriginEnabled(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readOriginEnabled(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.originEnabled(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOriginEnabled(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOriginEnabled(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of origin enabled of observed source")
  void test_origin_enabled_value_holder_unset() {
    Object holder = new Object();
    OriginEnabledValueHolder<Object> value = new OriginEnabledValueHolder<>(holder);
    OriginEnabledVO vo = OriginEnabledVO.from(true);
    value.originEnabled(vo);
    Assertions.assertSame(holder, value.unsetOriginEnabledIfMatches("originEnabled_other"));
    Assertions.assertTrue(value.getOriginEnabledValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOriginEnabledIfMatches("originEnabled"));
    Assertions.assertFalse(value.getOriginEnabledValue().isPresent(),
        "The field name must clear the value");
    value.originEnabled(vo);
    Assertions.assertSame(holder, value.unsetOriginEnabled());
    Assertions.assertFalse(value.getOriginEnabledValue().isPresent(), "Unset must clear the value");
  }
}
